         p.procost AS cost, p.prorows AS nrows
    FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace;

CREATE OR REPLACE FUNCTION public.mcp_authorize_view(p_request_id text, p_browser_binding_sha256 bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_uid   uuid := auth.uid();
  v_nonce text;
  v_req   public.mcp_authorization_requests%ROWTYPE;
  v_r     jsonb;
BEGIN
  /*BODY:4263-5*/
  IF v_uid IS NULL THEN
    RETURN public._mcp_refuse('not_signed_in');
  END IF;
  IF public._mcp_impersonating(v_uid) IS NOT FALSE THEN
    RETURN public._mcp_refuse('impersonating');
  END IF;
  IF (SELECT s.enabled FROM public.mcp_settings s WHERE s.id) IS NOT TRUE THEN
    RETURN public._mcp_refuse('disabled');
  END IF;
  v_nonce := public._mcp_b64url(uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid()));
  UPDATE public.mcp_authorization_requests r
     SET claimed_by = v_uid,
         consent_nonce_sha256 = sha256(convert_to(v_nonce, 'UTF8')),
         scope = public._mcp_granted_scope(r.scope)                                              /*SCOPE:view_store*/
   WHERE r.id = p_request_id
     AND r.status = 'pending'
     AND r.expires_at > now()
     AND r.browser_binding_sha256 = p_browser_binding_sha256
     AND (r.claimed_by IS NULL OR r.claimed_by = v_uid)
  RETURNING r.* INTO v_req;
  IF v_req.id IS NULL THEN
    RETURN public._mcp_refuse('request_invalid');
  END IF;
  SELECT jsonb_build_object(
           'ok', true,
           'request_id', v_req.id,
           'client_name', c.client_name,
           'provider', a.provider,
           'redirect_host', substring(v_req.redirect_uri FROM '^https://([^/]+)'),
           'scope', v_req.scope,                                                                  /*SCOPE:view*/
           'notice_version', s.notice_version,
           'nonce', v_nonce,
           'replaces_existing', EXISTS (SELECT 1 FROM public.mcp_connections x
                                         WHERE x.user_id = v_uid
                                           AND x.redirect_uri = v_req.redirect_uri
                                           AND x.status = 'active'))
    INTO v_r
    FROM public.mcp_oauth_clients c
    JOIN public.mcp_redirect_allowlist a ON a.redirect_uri = v_req.redirect_uri
    JOIN public.mcp_settings s ON s.id
   WHERE c.client_id = v_req.client_id;
  RETURN coalesce(v_r, public._mcp_refuse('request_invalid'));
END
$fn$;
REVOKE ALL ON FUNCTION public.mcp_authorize_view(text, bytea) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mcp_authorize_view(text, bytea) TO authenticated;

DELETE FROM supabase_migrations.schema_migrations WHERE version = '20261118170000';

DO $postager$
DECLARE v jsonb; v_want jsonb;
BEGIN
  SELECT jsonb_build_object(
    'view_md5', (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_authorize_view(text,bytea)'::regprocedure),
    'view_md5_before', (SELECT src_md5 FROM pg_temp.ag_rb_before WHERE sig = 'public.mcp_authorize_view(text,bytea)'::regprocedure::text),
    'changed', (SELECT coalesce(array_agg(b.sig ORDER BY b.sig COLLATE "C"), '{}') FROM pg_temp.ag_rb_before b
         WHERE NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows AND md5(p.prosrc) = b.src_md5)),
    'view_attributes_unchanged', EXISTS (SELECT 1 FROM pg_temp.ag_rb_before b JOIN pg_proc p ON p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol AND p.proisstrict = b.strict
                             AND p.proleakproof = b.leakproof AND p.proparallel = b.parallel AND p.procost = b.cost AND p.prorows = b.nrows WHERE b.sig = 'public.mcp_authorize_view(text,bytea)'::regprocedure::text),
    'view_owner_volatile_definer_path_grants', (SELECT p.proowner = 'postgres'::regrole::oid AND p.provolatile = 'v' AND p.prosecdef AND array_to_string(p.proconfig, ',') = 'search_path=""'
          AND p.proacl::text = '{postgres=X/postgres,authenticated=X/postgres}'
          AND has_function_privilege('authenticated', p.oid, 'EXECUTE') AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
          AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE')
        FROM pg_proc p WHERE p.oid = 'public.mcp_authorize_view(text,bytea)'::regprocedure),
    'added', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_temp.ag_rb_before b WHERE b.sig = p.oid::regprocedure::text)),
    'anon_mcp_17', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118170000')) INTO v;
  v_want := CASE WHEN v ->> 'view_md5_before' = 'a9b5a3de003671600e0033d7d952d804' THEN '[]'::jsonb ELSE to_jsonb(ARRAY['public.mcp_authorize_view(text,bytea)'::regprocedure::text]) END;
  IF v ->> 'view_md5' IS DISTINCT FROM 'a9b5a3de003671600e0033d7d952d804'
     OR v -> 'changed' IS DISTINCT FROM v_want
     OR (v ->> 'view_attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'view_owner_volatile_definer_path_grants')::boolean IS NOT TRUE
     OR v -> 'added' <> '[]'::jsonb OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'ledger')::int <> 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261118170000 FAILED, nothing applied: %', v;
  END IF;
  RAISE NOTICE 'ROLLBACK POST-CHECK 20261118170000 OK: %', v;
END
$postager$;

DO $after$
BEGIN
  PERFORM pg_temp.rec('rb_view_md5', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_authorize_view(text,bytea)'::regprocedure)));
  PERFORM pg_temp.rec('rb_md5_equals_before_apply', to_jsonb((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.mcp_authorize_view(text,bytea)'::regprocedure)
                                                             = (SELECT v #>> '{}' FROM pg_temp.ag_out WHERE k = 'view_md5_before_apply')));
  PERFORM pg_temp.rec('rb_acl', to_jsonb((SELECT proacl::text FROM pg_proc WHERE oid = 'public.mcp_authorize_view(text,bytea)'::regprocedure)));
  PERFORM pg_temp.rec('rb_ledger', to_jsonb((SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118170000')));
  PERFORM pg_temp.rec('rb_c_age', jsonb_build_object('result', left(pg_temp.iso('c_age'), 300)));
  PERFORM pg_temp.rec('rb_c_refusals', jsonb_build_object('result', left(pg_temp.iso('c_refusals'), 300)));
  PERFORM pg_temp.rec('now_unchanged_since_fixtures', to_jsonb(now() = (SELECT (v #>> '{}')::timestamptz FROM pg_temp.ag_out WHERE k = 'fx_now')));
  PERFORM pg_temp.rec('t_end', to_jsonb(clock_timestamp()));
  RAISE EXCEPTION 'AGE_RESULT %', (SELECT jsonb_object_agg(k, v) FROM pg_temp.ag_out);
END
$after$;
